// typed_a2_check_rt.h: round A2's differential check (a2_typed_check.cpp, generated by tools/typed_lift2.py --check-tu;
// docs/decomp_a2.md). Only the check translation unit and the offline harness (tools/a2_harness.cpp) include it.
//
// As A1's check (typed_a1_check_rt.h: two legs on logged memory, the reference a copy of the lifted text on a copy of
// the caller's context, the typed function on the values the adapter passes), with two additions:
//   - the reference's calls go to the callees' lifted texts (A1's and A2's references, a2ck::refCall), on the same
//     logged state, without the clock or the function table;
//   - the stores below the entry sp (the dead stack: the reference's frames, which the typed functions keep in host
//     arrays) are left out of the comparison of the two legs' stores.
#pragma once

#define A2_CHECK_TU 1
#include "typed_a1_check_rt.h"
#include "typed_a2_rt.h"

namespace a2ck
{
    extern const a1ck::CkEntry kEntries[];
    extern const uint32_t kEntryCount;
    inline a1ck::CkStats g_stats;
    inline uint64_t g_unknownCalls = 0, g_frameStores = 0;
    constexpr uint32_t kDeadStack = 0x40000u; // a store in [sp - this, sp) is to the dead stack

    inline void ckUnknownCall(uint32_t) { ++g_unknownCalls; }

    inline bool ckBegin(int id, uint8_t *ram, PS2Runtime *rt)
    {
        a1ck::CkState &s = a1ck::ckState();
        if (s.active)
        {
            ++g_stats.nested;
            return false;
        }
        s.active = true;
        s.n[0] = s.n[1] = 0;
        s.cur = 0;
        s.ovf = s.io = false;
        s.ram = ram;
        s.rt = rt;
        ++g_stats.calls;
        if (id >= 0 && static_cast<uint32_t>(id) < a1ck::kMaxFunctions)
            ++g_stats.perCalls[id];
        return true;
    }

    // a1ck::ckEnd's comparison on a2's stats, after the dead-stack stores are taken out of both logs
    inline void ckEnd(int id, const R5900Context *in, const R5900Context &ref, int kind, uint64_t v0, float f0, uint32_t dg, uint32_t df)
    {
        a1ck::CkState &s = a1ck::ckState();
        const uint32_t sp = static_cast<uint32_t>(Ps2GprU64(in, 29));
        for (int c = 0; c < 2; ++c)
        {
            int k = 0;
            for (int i = 0; i < s.n[c] && i < a1ck::kMaxStores; ++i)
            {
                const a1ck::CkStore &w = s.log[c][i];
                if (sp - w.a - 1u < kDeadStack) // w.a in [sp - kDeadStack, sp)
                {
                    g_frameStores += c == 0;
                    continue;
                }
                s.log[c][k++] = w;
            }
            s.n[c] = k;
        }
        a1ck::ckEndOn(g_stats, kEntries, kEntryCount, id, in, ref, kind, v0, f0, dg, df);
    }

    inline void ckReport(unsigned long long frame)
    {
        const a1ck::CkStats &g = g_stats;
        uint32_t fns = 0;
        for (uint32_t i = 0; i < kEntryCount && i < a1ck::kMaxFunctions; ++i)
            fns += g.perCalls[i] ? 1u : 0u;
        std::fprintf(stderr, "[a2] frame %llu: checks %llu (functions reached %u of %u) differ %llu (ret %llu mem %llu pc %llu sp %llu other %llu); "
                             "slow-path loads %llu, log overflow %llu, nested %llu, unknown calls %llu, dead-stack stores %llu; scratch slots changed by the reference %llu%s%s\n",
                     frame, (unsigned long long)g.calls, fns, kEntryCount, (unsigned long long)g.differ, (unsigned long long)g.ret,
                     (unsigned long long)g.mem, (unsigned long long)g.pc, (unsigned long long)g.sp, (unsigned long long)g.other,
                     (unsigned long long)g.io, (unsigned long long)g.ovf, (unsigned long long)g.nested, (unsigned long long)g_unknownCalls,
                     (unsigned long long)g_frameStores, (unsigned long long)g.droppedChanged, g.firstId >= 0 ? "; first: " : "", g.first);
    }
}
